class Solution:
    def deleteNode(self, node: ListNode) -> None:
        nxt = node.next
        node.val = nxt.val
        node.next = nxt.next

impl Solution {
  pub fn delete_node(node: &mut ListNode) {
    let mut next = node.next.take().unwrap();
    node.val = next.val;
    node.next = next.next.take();
  }
}

const deleteNode = (node: ListNode): void => {
  const next = node.next!;
  node.val = next.val;
  node.next = next.next;
};
